scratch_sources./tmp/cod-world-tls-audit/entry.cod:
using symbol "std:io" @assert;
using symbol "std:io" @print;
using "vocabulary.cod" Words;
symbol from "vocabulary.cod" @state;
symbol from "vocabulary.cod" @state as @same_state;
symbol from "vocabulary.cod" @bias;
symbol first::proc() -> i64, second::proc() -> i64, view::proc() -> ref<Words>;
using "first.cod" @read as @first;
using "second.cod" @read as @second;
using "first.cod" @view as @view;
symbol arena::region;
effect @arena <- region(4096u64);
effect @state <- alloc @arena Words(1u64, 30);
effect @bias <- 3;
behave @assert(perform @first() == 11);
behave @assert(perform @second() == 22);
behave @assert(behave @first() == 33);
behave @assert(behave @second() == 33);
for (i in 0u32 .. 3u32) {
  effect @state <- alloc @arena Words(1u64, 40 + i64(i));
  effect @bias <- 4;
  behave @assert(@same_state[0u32] == 40 + i64(i));
  behave @assert(behave @first() == 44 + i64(i));
  behave @assert(perform @first() == 11);
  behave @assert(perform @second() == 22);
};
behave @assert(behave @first() == 33);
behave @assert(@same_state[0u32] == 30);
{
  let captured_view = perform @view();
  store(captured_view, 0u32, 15);
  behave @assert(perform @first() == 16);
  behave @assert(perform @second() == 22);
  behave @assert(behave @first() == 33);
};
behave @print(perform @first());
behave @print(perform @second());
behave @print(behave @first());

